func (q *Queries) ListUpstreamClientBackfillCandidates(ctx context.Context, arg ListUpstreamClientBackfillCandidatesParams) ([]ListUpstreamClientBackfillCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listUpstreamClientBackfillCandidates, arg.Cursor, arg.OrganizationID, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUpstreamClientBackfillCandidatesRow
	for rows.Next() {
		var i ListUpstreamClientBackfillCandidatesRow
		if err := rows.Scan(
			&i.McpServerID,
			&i.ProjectID,
			&i.OrganizationID,
			&i.UserSessionIssuerID,
			&i.RemoteBacked,
			&i.Hosted,
			&i.Proxied,
			&i.IssuerServerCount,
			&i.IssuerHasGateway,
			&i.LiveAssociations,
			&i.RemoteSessionClientID,
			&i.MetadataMatch,
			&i.PairLive,
			&i.PairRecorded,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

